private function resolve(): ?string
{
    if ($this->resolved) return $this->binary;
    $this->resolved = true;

    $configured = config('services.pdf.binary');
    if (is_string($configured) && trim($configured) !== '') {
        $this->binary = $this->works(trim($configured)) ? trim($configured) : null;
        return $this->binary;
    }

    foreach (self::CANDIDATES as $candidate) {
        if ($this->works($candidate)) { $this->binary = $candidate; return $candidate; }
    }
    return null;
}

private function works(string $binary): bool
{
    try {
        $process = new Process([$binary, '--version'], null, null, null, 10);
        $process->run();
        return $process->isSuccessful();
    } catch (\Throwable) {
        return false;
    }
}
